if(!UnityEditor.EditorApplication.isPlaying)throw new System.InvalidOperationException("F7 doğrulaması Play modunda çalıştırılmalı.");
var h=UnityEngine.Object.FindFirstObjectByType<Corrigible.Fx.FxRaidHud>();var b=h.board;var c=h.clock;c.enabled=false;c.Freeze();var camera=b.boardCamera;var previous=camera.targetTexture;var rt=new UnityEngine.RenderTexture(1280,720,24);camera.targetTexture=rt;UnityEngine.Canvas.ForceUpdateCanvases();camera.Render();b.RefreshProjection(true);h.RefreshLayout(true);var samples=new System.Collections.Generic.List<object>();
try{foreach(var mode in new[]{"machines","result"}){h.LoadScreen(mode=="machines"?1:7);h.CompleteAnimations();b.nodeOrb.RenderFixed(.025,100);h.stateOrb.RenderFixed(.025,100);c.Resume();double start=c.Now;string dir="/private/tmp/CorrigibleFxF7_"+mode;System.IO.Directory.CreateDirectory(dir);
for(int frame=0;frame<240;frame++){double time=start+frame/30.0;c.Advance(time);if(frame==30){if(mode=="machines"){h.EndTurn();h.EndTurn();}else h.UseAbilityOn(new UnityEngine.Vector2Int(6,3));}if(mode=="machines"&&frame==105)h.SpeedUpMachines(true);UnityEngine.Canvas.ForceUpdateCanvases();camera.Render();var active=UnityEngine.RenderTexture.active;UnityEngine.RenderTexture.active=rt;var texture=new UnityEngine.Texture2D(1280,720,UnityEngine.TextureFormat.RGB24,false);texture.ReadPixels(new UnityEngine.Rect(0,0,1280,720),0,0);texture.Apply();System.IO.File.WriteAllBytes(dir+"/"+frame.ToString("0000")+".png",texture.EncodeToPNG());UnityEngine.Object.DestroyImmediate(texture);UnityEngine.RenderTexture.active=active;if(frame%10==0)samples.Add(new{mode,seconds=frame/30.0,phase=h.Model.Phase,h.Model.Turn,machine=h.source.MachineRunning,h.Model.FastMachines,finished=h.Model.Finished,corners=h.corners.alpha,memo=System.Array.Find(h.slots,x=>x.key=="result").popup.group.alpha,stamp=System.Array.Find(h.slots,x=>x.key=="result.stamp").group.alpha,orbAlpha=h.collapsedOrb.image.color.a,orbScale=h.collapsedOrb.transform.localScale.x});}c.Freeze();}}
finally{camera.targetTexture=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);c.Freeze();h.LoadScreen(1);c.Advance(c.Now);}
System.IO.File.WriteAllText("Docs/UI_Fx/captures/F7/motion-timing.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{frames=480,fps=30,secondsEach=8,samples},Newtonsoft.Json.Formatting.Indented));return new{frames=480,secondsEach=8};
